CREATE TABLE IF NOT EXISTS market_observations(id bigserial PRIMARY KEY,observation_id text UNIQUE,session_id text,market_context_id text,segment_id text,context_version integer,asset_raw text,asset_canonical text,market_type text,observed_at timestamptz,processed_at timestamptz,price numeric,price_source text,price_confidence numeric,timeframe_seconds integer,expiration_seconds integer,investment_value numeric,position_exists boolean,position_direction text,position_confidence numeric,frame_id text,observation_quality text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS market_observations_segment_idx ON market_observations(session_id,segment_id,observed_at DESC);
